/* prog30_escape_unescape – reproduced from the analysed binary
 *
 * The original binary implements two simple commands:
 *
 *   prog30_escape_unescape escape   <string>
 *   prog30_escape_unescape unescape <string>
 *
 * *escape*  converts a few special characters to their C‑style
 * back‑slash escapes (\\, \", newline and tab).  All other characters
 * are copied unchanged.
 *
 * *unescape* performs the inverse transformation.  It recognises the
 * same four escape sequences (\\, \", \n, \t).  Any other back‑slash
 * sequence (including a trailing back‑slash) is considered invalid
 * and the program prints the literal string "INVALID".
 *
 * If the command line does not contain exactly three arguments the
 * program prints "USAGE".  If the first argument is neither "escape"
 * nor "unescape" the program prints "INVALID_MODE".
 *
 * The original binary limited the input length to 1023 characters;
 * this implementation follows the same limit – longer inputs are
 * treated as a usage error (the original binary printed "USAGE" in
 * that case).
 *
 * The program writes its result to stdout and returns 0 on success,
 * 0 on the usage/invalid cases as well (the original binary behaved
 * that way).
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_INPUT 1024   /* 0x400, same as the original binary limit */

/* ------------------------------------------------------------------ */
/* Escape a string – only the characters that the original binary
 * handled are escaped.  The result is stored in a dynamically allocated
 * buffer that the caller must free. */
static char *escape_string(const char *src)
{
    size_t len = strlen(src);
    /* In the worst case every character becomes two characters. */
    char *dst = malloc(len * 2 + 1);
    if (!dst) return NULL;

    size_t out = 0;
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)src[i];
        switch (c) {
            case '\\':
                dst[out++] = '\\';
                dst[out++] = '\\';
                break;
            case '"':
                dst[out++] = '\\';
                dst[out++] = '"';
                break;
            case '\n':
                dst[out++] = '\\';
                dst[out++] = 'n';
                break;
            case '\t':
                dst[out++] = '\\';
                dst[out++] = 't';
                break;
            default:
                dst[out++] = c;
                break;
        }
    }
    dst[out] = '\0';
    return dst;
}

/* ------------------------------------------------------------------ */
/* Un‑escape a string – recognises the same four escape sequences.
 * Returns a newly allocated string on success, or NULL if an invalid
 * escape sequence is encountered. */
static char *unescape_string(const char *src)
{
    size_t len = strlen(src);
    char *dst = malloc(len + 1);          /* result cannot be longer */
    if (!dst) return NULL;

    size_t out = 0;
    for (size_t i = 0; i < len; ++i) {
        if (src[i] != '\\') {
            dst[out++] = src[i];
            continue;
        }

        /* Back‑slash found – need a following character */
        if (i + 1 >= len) {
            free(dst);
            return NULL;                 /* invalid: trailing '\\' */
        }

        char nxt = src[i + 1];
        switch (nxt) {
            case '\\':
                dst[out++] = '\\';
                break;
            case '"':
                dst[out++] = '"';
                break;
            case 'n':
                dst[out++] = '\n';
                break;
            case 't':
                dst[out++] = '\t';
                break;
            default:
                free(dst);
                return NULL;             /* invalid escape */
        }
        i++;    /* consumed the escape character as well */
    }
    dst[out] = '\0';
    return dst;
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];

    if (strlen(input) > MAX_INPUT) {
        /* The original binary treated an overly long input as a usage error */
        puts("USAGE");
        return 0;
    }

    if (strcmp(mode, "escape") == 0) {
        char *out = escape_string(input);
        if (!out) return 0;               /* allocation failure – silent exit */
        puts(out);
        free(out);
        return 0;
    }

    if (strcmp(mode, "unescape") == 0) {
        char *out = unescape_string(input);
        if (!out) {
            puts("INVALID");
            return 0;
        }
        puts(out);
        free(out);
        return 0;
    }

    /* Anything else is an invalid mode */
    puts("INVALID_MODE");
    return 0;
}
